import sys

class ToDoList:
    def __init__(self):
        self.todo_list = {}
        self.history = []

    def set(self, ai, xi):
        self.todo_list[ai] = xi
        self.history.append(('set', ai, xi))

    def remove(self, ai):
        if ai in self.todo_list:
            del self.todo_list[ai]
            self.history.append(('remove', ai))

    def query(self, ai):
        if ai in self.todo_list:
            xi = self.todo_list[ai]
            count = sum(1 for key, value in self.todo_list.items() if value < xi)
            return count
        else:
            return -1

    def undo(self, di):
        for _ in range(di):
            if self.history:
                last_operation = self.history.pop()
                if last_operation[0] == 'set':
                    self.todo_list.pop(last_operation[1], None)
                elif last_operation[0] == 'remove':
                    self.todo_list[last_operation[1]] = None

# Read input
q = int(sys.stdin.readline().strip())
operations = [sys.stdin.readline().strip().split() for _ in range(q)]

# Process operations
todo_list = ToDoList()
for i, operation in enumerate(operations):
    if operation[0] == 'set':
        ai, xi = operation[1], int(operation[2])
        todo_list.set(ai, xi)
    elif operation[0] == 'remove':
        ai = operation[1]
        todo_list.remove(ai)
